CREATE TABLE IF NOT EXISTS dossier_records (owner_id TEXT NOT NULL, kind TEXT NOT NULL, id TEXT NOT NULL, revision INTEGER NOT NULL, value TEXT NOT NULL CHECK(json_valid(value)), updated_at INTEGER NOT NULL, PRIMARY KEY(owner_id,kind,id));
CREATE INDEX IF NOT EXISTS dossier_records_owner_kind ON dossier_records(owner_id,kind,updated_at,id);
CREATE TABLE IF NOT EXISTS dossier_jobs (owner_id TEXT NOT NULL, id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('inventory','extract','synthesize','assess')), target_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','succeeded','failed','cancelled')), attempts INTEGER NOT NULL DEFAULT 0, lease TEXT, lease_until INTEGER, available_at INTEGER NOT NULL, dispatched_at INTEGER, progress TEXT NOT NULL DEFAULT '{}', error TEXT, created_at INTEGER NOT NULL, PRIMARY KEY(owner_id,id), UNIQUE(owner_id,idempotency_key));
CREATE INDEX IF NOT EXISTS dossier_jobs_dispatch ON dossier_jobs(state,available_at,lease_until,dispatched_at);
